import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Build, deployment and quality audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/BUILD-DEPLOYMENT-AND-QUALITY.html"}],["meta",{"property":"og:title","content":"Build, deployment and quality audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/BUILD-DEPLOYMENT-AND-QUALITY.html"}],["meta",{"name":"twitter:title","content":"Build, deployment and quality audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/BUILD-DEPLOYMENT-AND-QUALITY.md","filePath":"audits/BUILD-DEPLOYMENT-AND-QUALITY.md","lastUpdated":1794227887000}`),a={name:`audits/BUILD-DEPLOYMENT-AND-QUALITY.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="build-deployment-and-quality-audit" tabindex="-1">Build, deployment and quality audit <a class="header-anchor" href="#build-deployment-and-quality-audit" aria-label="Permalink to “Build, deployment and quality audit”">​</a></h1><h2 id="deploy-01-—-dev-web-docs-publishing-and-dev-assembly" tabindex="-1">DEPLOY-01 — Dev web/docs publishing and <code>/dev/</code> assembly <a class="header-anchor" href="#deploy-01-—-dev-web-docs-publishing-and-dev-assembly" aria-label="Permalink to “DEPLOY-01 — Dev web/docs publishing and /dev/ assembly”">​</a></h2><p><strong>Current status: COMPLETED for the active <code>dev</code> delivery path in PR #80.</strong> Dev web and documentation are published independently to <code>dev_pages-web-artifact</code> and <code>dev_pages-docs-artifact</code>; the dev Pages assembler composes them beneath <code>site/dev/</code>. The user confirmed that the merged preview works. Main-branch integration is intentionally deferred until work moves to <code>main</code>; it is not a blocker for the current dev workflow.</p><p><strong>Severity:</strong> P2 (historical deployment-isolation concern; current dev acceptance is met).</p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/.github/workflows/pages.yml" target="_blank" rel="noreferrer">dev pages assembler</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/.github/workflows/dev-web-pages.yml" target="_blank" rel="noreferrer">dev web publisher</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/.github/workflows/dev-docs-pages.yml" target="_blank" rel="noreferrer">dev docs publisher</a>.</p><p><strong>Current controls:</strong></p><ul><li>Independent dev web/docs publishing avoids making web changes wait for benchmark generation.</li><li>The assembler extracts dev components beneath <code>site/dev/</code> and asserts the root, web and docs entry points exist.</li><li>Dev output uses the <code>/FD-Calculator/dev/</code> base, noindex metadata and a visible preview banner.</li><li>Persistent dev artifact/state refs use the <code>dev_</code> prefix.</li><li>The Pages deployment concurrency group serializes site deployments.</li><li>The root <code>robots.txt</code> permits crawling so search engines can read the preview pages&#39; <code>noindex,nofollow</code> directives; preview URLs remain excluded from the production sitemap.</li></ul><p><strong>Deferred follow-up:</strong> when work moves to <code>main</code>, port and verify the preview-aware assembler there so a main deployment also retains the latest dev subtree. Do not change or block the current dev pipeline for that future task.</p><h2 id="crawler-and-sitemap-controls-—-verified-positive-control" tabindex="-1">Crawler and sitemap controls — verified positive control <a class="header-anchor" href="#crawler-and-sitemap-controls-—-verified-positive-control" aria-label="Permalink to “Crawler and sitemap controls — verified positive control”">​</a></h2><p><strong>Current status: IMPLEMENTED on <code>dev</code>; no open SEO-01 finding.</strong> The production docs build starts with the VitePress documentation sitemap, merges the canonical site root and <code>/web/</code> application URL into it, and publishes the assembled file at the site root. The preview build skips sitemap assembly and removes any docs sitemap from its output. The root <code>robots.txt</code> permits crawling and declares the production sitemap; dev preview HTML carries <code>noindex,nofollow</code> and preview URLs are excluded from the sitemap. The dev web build rewrites canonical URLs and sets <code>noindex,nofollow</code>; VitePress preview metadata also sets noindex.</p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/scripts/build-docs-site.sh" target="_blank" rel="noreferrer">docs build script</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/docs/.vitepress/config.mts" target="_blank" rel="noreferrer">VitePress config</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/robots.txt" target="_blank" rel="noreferrer">robots.txt</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/scripts/build-web-site.sh" target="_blank" rel="noreferrer">dev web build</a>.</p><p><strong>Regression protection:</strong> the Pages pipeline contract test now asserts that production sitemap assembly includes the canonical root and <code>/web/</code> URLs, that preview output removes its docs sitemap, and that the root robots policy excludes the dev subtree.</p><p>Robots directives are crawler guidance, not access control. Preserve the existing production sitemap merge and preview noindex behaviour when changing build paths.</p><h2 id="build-pipeline-assessment" tabindex="-1">Build pipeline assessment <a class="header-anchor" href="#build-pipeline-assessment" aria-label="Permalink to “Build pipeline assessment”">​</a></h2><h3 id="strengths" tabindex="-1">Strengths <a class="header-anchor" href="#strengths" aria-label="Permalink to “Strengths”">​</a></h3><ul><li>Web and documentation are produced as separate artifacts, which avoids making a web-only change wait for the documentation benchmark pipeline.</li><li>The docs workflow generates benchmark data, validates expected scenario counts/parameter sweeps and then builds the docs component.</li><li>The Pages assembler composes independently published web/docs artifacts and tracks their SHAs to avoid redundant deployments.</li><li>The dev workflow uses <code>FD_CAL_PREVIEW=true</code>, a dedicated <code>dev_pages-preview-artifact</code> branch, noindex metadata and a visible preview banner.</li><li>The preview output is path-prefixed so relative web assets and docs base URLs resolve under <code>/FD-Calculator/dev/</code>.</li><li>The preview workflow uses short-lived Actions artifacts named <code>dev-web-site</code> and <code>dev-docs-site</code>; persistent Git branches are prefixed <code>dev_</code>.</li></ul><h3 id="verification-still-required" tabindex="-1">Verification still required <a class="header-anchor" href="#verification-still-required" aria-label="Permalink to “Verification still required”">​</a></h3><p>The current <code>dev</code> source revision contains the split publisher and assembler. The user confirmed the merged preview is working. The earlier in-progress deployment note has been superseded and is not current status.</p><p>After deployment, verify these paths:</p><ul><li><code>/FD-Calculator/dev/</code></li><li><code>/FD-Calculator/dev/web/</code></li><li><code>/FD-Calculator/dev/docs/</code></li></ul><p>Check that each page uses noindex metadata, all relative assets/data/worker requests stay under the dev path, the app displays the dev banner, and the production root still serves the main artifacts.</p><h2 id="qa-01-—-the-automated-suite-is-strong-on-node-contracts-but-lacks-browser-level-coverage" tabindex="-1">QA-01 — The automated suite is strong on Node contracts but lacks browser-level coverage <a class="header-anchor" href="#qa-01-—-the-automated-suite-is-strong-on-node-contracts-but-lacks-browser-level-coverage" aria-label="Permalink to “QA-01 — The automated suite is strong on Node contracts but lacks browser-level coverage”">​</a></h2><p><strong>Current status: IMPLEMENTED ON FOLLOW-UP BRANCH; AUTOMATED CI GREEN.</strong> A Playwright Chromium smoke suite runs in the shared test workflow for pushes to <code>dev</code>/<code>main</code> and PRs targeting those branches. Full workflow <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42574353592" target="_blank" rel="noreferrer">42574353592</a> passed the Node suite, syntax checks, production/dev builds, all six browser tests, documentation-preservation build and workflow YAML parsing. The suite covers app startup/privacy preferences, legal navigation, dev-preview noindex/path prefix, mobile overflow, keyboard focus/reduced motion, and an independently opened report with semantic headers, 320px overflow and print-width checks. Broader offline/chart report checks, actual print/PDF pagination, screen-reader, contrast and 200–400% zoom QA remain.</p><p><strong>Evidence:</strong> the repository contains tests for configuration, dates/foundations, cash-flow components, account provenance, runtime/ledger, strategy parity, search, worker contracts, report output, motion guidelines and Pages workflow contracts. The workflow runs <code>npm test</code>, syntax checks and static build checks.</p><p><strong>Gap:</strong> no Playwright/Cypress/WebDriver browser suite or screenshot/visual-regression runner was identified. Static source assertions do not verify rendered layout, keyboard focus order, screen-reader announcements, chart rendering, file import/export or actual GitHub Pages subpath behaviour.</p><p><strong>Recommendation:</strong> add a small browser smoke suite for:</p><ul><li>Load catalogue and render initial form.</li><li>Import/export valid and malicious JSON.</li><li>Run one deterministic simulation and download/open the standalone report.</li><li>Check no console errors and no failed same-origin requests.</li><li>Exercise 320px/mobile and desktop layouts.</li><li>Verify keyboard-only operation, validation error announcements and reduced motion.</li><li>Open the dev preview at the deployed subpath to catch base-path and worker/data URL regressions.</li></ul><h2 id="ci-and-release-quality" tabindex="-1">CI and release quality <a class="header-anchor" href="#ci-and-release-quality" aria-label="Permalink to “CI and release quality”">​</a></h2><ul><li>The Node.js test/syntax workflow passed on audited <code>dev</code> commit <code>caccaf26b4415ae783959e888ff45e33becdadf6</code> (<a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42553842534" target="_blank" rel="noreferrer">run 42553842534</a>); the independent dev web build/publish also passed (<a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42553842533" target="_blank" rel="noreferrer">run 42553842533</a>). The docs/benchmark publishing workflow was in progress when checked (<a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42553842591" target="_blank" rel="noreferrer">run 42553842591</a>).</li><li>No manual screen-reader/WCAG review, Lighthouse run, deployed CSP/header scan or external dependency/security scan was completed during this source review. The latest CI failure is tracked in the implementation plan.</li><li><code>npm ci</code> reports no installed dependencies beyond the project itself; VitePress is installed separately by the documentation build script without updating the lockfile. This is reproducible only to the extent that the VitePress version is pinned by the script.</li><li>Action references use version tags rather than immutable commit SHAs. Consider SHA pinning for higher supply-chain assurance, with automated update tooling.</li><li>Benchmark validation checks expected observation counts and parameter sweeps; it does not independently validate every bank-rate source or the financial correctness of each observation.</li></ul><h2 id="operational-recommendations" tabindex="-1">Operational recommendations <a class="header-anchor" href="#operational-recommendations" aria-label="Permalink to “Operational recommendations”">​</a></h2><ol><li>Keep the preview and production deployments serialized.</li><li>Preserve the previous successful production artifact if a component build fails.</li><li>Preserve the verified crawler controls: keep preview pages out of production sitemaps, keep the dev preview crawlable so crawlers can read <code>noindex,nofollow</code>, and exclude preview URLs from the production sitemap.</li><li>Add a smoke test for generated URLs and worker/module loading under the project subpath.</li><li>Defer porting the preview-aware Pages assembler to <code>main</code> until main-branch work begins; the current delivery target is <code>dev</code>.</li><li>Add a concise deployment runbook documenting how to inspect/roll back web, docs and dev artifact refs.</li></ol>`,31)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};